import re
import unicodedata
import hashlib

# Exact accent- and punctuation-normalized title or artist identity.
def exact_identity(r):
    def norm(value):
        value = unicodedata.normalize("NFKD", str(value or ""))
        value = "".join(c for c in value if not unicodedata.combining(c))
        return " ".join(re.findall(r"[a-z0-9]+", value.casefold()))

    def key(prefix, value):
        return prefix + hashlib.blake2s(value.encode("utf-8"), digest_size=8).hexdigest()

    out = []
    title = norm(r.get("title", ""))
    artist = norm(r.get("artist_name", ""))
    if title:
        out.append(key("et:", title))
    if artist:
        out.append(key("ea:", artist))
    return out


# Strip bracketed version notes and split compound or credited artist aliases.
def qualifier_and_alias(r):
    def fold(value):
        value = unicodedata.normalize("NFKD", str(value or ""))
        return "".join(c for c in value if not unicodedata.combining(c)).casefold()

    def norm(value):
        return " ".join(re.findall(r"[a-z0-9]+", fold(value)))

    def emit(prefix, value):
        return prefix + hashlib.blake2s(value.encode("utf-8"), digest_size=8).hexdigest()

    values = set()
    raw_title = str(r.get("title", "") or "")
    base = raw_title
    previous = None
    while previous != base:
        previous = base
        base = re.sub(r"\([^()]*\)|\[[^\[\]]*\]|\{[^{}]*\}", " ", base)
    base = norm(base)
    if base:
        values.add(("bt:", base))
        if ":" in raw_title:
            head = norm(raw_title.split(":", 1)[0])
            if len(head) >= 3:
                values.add(("bt:", head))
    for part in re.split(r"[/|]", raw_title):
        part = norm(part)
        if len(part) >= 4:
            values.add(("bt:", part))

    artist = fold(r.get("artist_name", ""))
    artist = re.sub(
        r"\b(?:featuring|feat(?:uring)?|ft|with|including|inc|organized\s+by)\.?\b",
        "|",
        artist,
    )
    artist = re.sub(r"\b(?:and|x|vs)\b", "|", artist)
    artist = re.sub(r"[;/_&+]", "|", artist)
    role_suffixes = {
        "band", "ensemble", "orchestra", "group", "crew", "quartet",
        "choir", "chorus", "collective", "trio",
    }
    for part in artist.split("|"):
        part = norm(part)
        part = re.sub(r"^the\s+", "", part)
        tokens = part.split()
        while len(tokens) > 1 and tokens[-1] in role_suffixes:
            tokens.pop()
        part = " ".join(tokens)
        if len(part) >= 3:
            values.add(("ac:", part))

    return sorted(emit(prefix, value) for prefix, value in values)


# Adjacent lexical anchors shared across titles and releases, including migrated text.
def adjacent_anchor(r):
    def tokens(value):
        value = unicodedata.normalize("NFKD", str(value or ""))
        value = "".join(c for c in value if not unicodedata.combining(c)).casefold()
        return re.findall(r"[a-z0-9]+", value)

    def emit(value):
        return "bg:" + hashlib.blake2s(value.encode("utf-8"), digest_size=8).hexdigest()

    anchors = set()
    for field in ("title", "release"):
        seq = tokens(r.get(field, ""))
        for left, right in zip(seq, seq[1:]):
            if max(len(left), len(right)) >= 4:
                anchors.add(left + "\x1f" + right)
    return sorted(emit(value) for value in anchors)


# Vowel-insensitive token signatures tolerate spelling and transliteration variation.
def consonant_signature(r):
    def words(value):
        value = unicodedata.normalize("NFKD", str(value or ""))
        value = "".join(c for c in value if not unicodedata.combining(c)).casefold()
        return re.findall(r"[a-z0-9]+", value)

    def signature(word):
        compact = re.sub(r"[^a-z0-9]", "", word)
        consonants = re.sub(r"[aeiou]", "", compact)
        consonants = re.sub(r"(.)\1+", r"\1", consonants)
        return consonants if len(consonants) >= 3 else compact[:4]

    def emit(value):
        return "cs:" + hashlib.blake2s(value.encode("utf-8"), digest_size=8).hexdigest()

    signatures = set()
    for field in ("title", "artist_name"):
        for word in words(r.get(field, "")):
            if len(word) >= 5:
                code = signature(word)
                if len(code) >= 3:
                    signatures.add(code)
    return sorted(emit(value) for value in signatures)


SCHEMES = {
    "exact_identity": exact_identity,
    "qualifier_and_alias": qualifier_and_alias,
    "adjacent_anchor": adjacent_anchor,
    "consonant_signature": consonant_signature,
}
